"""Implementation of actions for the Field pane in the XVI application"""

from interops.libraries.squish_actions import CommonActions
from interops.libraries.xvi.interactions.objects.xvi_core_objects import Xvi_MainPage
from interops.libraries.xvi.interactions.objects.xvi_field_objects import Xvi_field_page
from interops.libraries.xvi.interactions.objects.xvi_treatment_objects import Xvi_Treatment_page
from interops.libraries.xvi.interactions.objects.xvi_patient_objects import Xvi_Patient_page

def __find_field_window() -> bool:
    """Searches for the field window of xvi. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Xvi_field_page.field_Window) is not None else False

def __find_field_errordialog() -> bool:
    """Searches for the field error dialog of xvi. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(Xvi_MainPage.intuity_XVI_Default_Database_dialog) is not None else False

def open_field_newPage() -> bool:
    """Open a new Field window from main menu
    :return: True or False
    :rtype: bool
    """
    CommonActions.left_click_object(Xvi_Patient_page.Patient_ListItem)
    CommonActions.left_click_object(Xvi_Treatment_page.Treatment_ListItem)
    CommonActions.left_click_object(Xvi_field_page.field_new_button)
    return __find_field_window()

def typeText_in_field_id(fieldID: str) -> None:
    """Locates the main New Field Registration window > types a given fieldID string into the  fieldID text box.

    :param str fieldID: fieldID string to be typed into the first name text box
    """
    if __find_field_window():
         CommonActions.type_in_textfield(Xvi_field_page.field_Field_ID_Edit,fieldID)

def typeText_in_field_description(fieldDescription: str) -> None:
    """Locates the main New Field Registration window > types a given fieldDescription string into the fieldDescription text box.

    :param str fieldDescription: fieldDescription string to be typed into the first name text box
    """
    if __find_field_window():
         CommonActions.type_in_textfield(Xvi_field_page.field_Description_Edit,fieldDescription)

def typeText_in_field_site(fieldSite: str) -> None:
    """Locates the main New Field Registration window > types a given fieldSite string into the fieldSite text box.

    :param str fieldSite: fieldSite string to be typed into the first name text box
    """
    if __find_field_window():
        CommonActions.type_in_textfield(Xvi_field_page.field_Site_Edit,fieldSite)

def select_inactive() -> None:
    """select inactive checkbox
    """
    if __find_field_window():
        CommonActions.left_click_object(Xvi_field_page.field_Inactive_CheckBox)

def clickOK() -> bool:
    """select inactive checkbox
    """
    if __find_field_window():
        CommonActions.left_click_object(Xvi_field_page.field_OK_Button)
        if __find_field_errordialog():
            CommonActions.left_click_object(Xvi_MainPage.intuity_XVI_Default_Database_XVI_OK_Button)  #???
            CommonActions.left_click_object(Xvi_field_page.field_Cancel_Button)
    return True if CommonActions.wait_for_object_to_disappear(Xvi_field_page.field_Window) is not None else False